export const units={in:1,ft:12,mm:1/25.4,cm:1/2.54,m:1000/25.4};
export function parseMeasure(raw){const s=String(raw).trim();if(!s)throw Error('Enter a measurement.');let value;if(/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(s))value=Number(s);else{const m=s.match(/^([+-]?)(?:(\d+)\s+)?(\d+)\s*\/\s*(\d+)$/);if(!m)throw Error('Use a number or fraction, like 12.375 or 12 3/8.');if(Number(m[4])===0)throw Error('A fraction cannot have a zero denominator.');value=(m[1]==='-'?-1:1)*(Number(m[2]||0)+Number(m[3])/Number(m[4]));}if(!Number.isFinite(value)||Math.abs(value)>1e12)throw Error('Enter a measurement no larger than 1 trillion.');return value;}
function gcd(a,b){while(b){[a,b]=[b,a%b];}return a;}
export function fraction(value,denominator=64){const n=Math.round(Math.abs(value)*denominator);const whole=Math.floor(n/denominator);const remainder=n%denominator;const d=gcd(remainder,denominator);return (value<0&&n>0?'-':'')+(whole||!remainder?String(whole):'')+(whole&&remainder?' ':'')+(remainder?`${remainder/d}/${denominator/d}`:'');}
export function format(value){return Number(value.toFixed(6)).toLocaleString('en-US',{maximumFractionDigits:6});}
export function boardFeet(thickness,width,length,quantity,metric=false){if(![thickness,width,length,quantity].every(v=>Number.isFinite(v)&&v>0)||!Number.isInteger(quantity))throw Error('Use positive dimensions and a whole-number quantity.');const single=metric?(thickness/25.4)*(width/25.4)*(length/0.3048)/12:thickness*width*length/12;const total=single*quantity;if(!Number.isFinite(total))throw Error('These dimensions are too large.');return {single,total,cubic:total/12};}
